
-- Contoso Industrial service claim system
-- Generated by scenario/build/gen_db.py - do not edit by hand.
-- Dialect: mssql

DROP TABLE IF EXISTS ClaimAdjudicationDraft;
DROP TABLE IF EXISTS EvidenceRequest;
DROP TABLE IF EXISTS GoodwillEscalation;
DROP TABLE IF EXISTS TsbApplicability;
DROP TABLE IF EXISTS GoodwillAuthority;
DROP TABLE IF EXISTS ServiceHistory;
DROP TABLE IF EXISTS AssetTelemetry;
DROP TABLE IF EXISTS Claims;
DROP TABLE IF EXISTS Assets;
DROP TABLE IF EXISTS Parts;
DROP TABLE IF EXISTS Dealers;

CREATE TABLE Dealers (
    dealer_id            NVARCHAR(40) PRIMARY KEY,
    name                 NVARCHAR(200) NOT NULL,
    region               NVARCHAR(40) NOT NULL,
    currency             NVARCHAR(40) NOT NULL,
    uplift_pct           DECIMAL(5,2) NOT NULL,
    agreement_ref        NVARCHAR(40) NOT NULL,
    submission_sla_days  INT NOT NULL
);

CREATE TABLE Parts (
    part_no        NVARCHAR(40) PRIMARY KEY,
    description    NVARCHAR(200) NOT NULL,
    family         NVARCHAR(40) NOT NULL,
    component      NVARCHAR(40),
    supersedes     NVARCHAR(40),
    superseded_by  NVARCHAR(40),
    price_inr      DECIMAL(14,2),
    price_eur      DECIMAL(14,2),
    price_sgd      DECIMAL(14,2)
);

CREATE TABLE Assets (
    serial              NVARCHAR(40) PRIMARY KEY,
    family              NVARCHAR(40) NOT NULL,
    dealer_id           NVARCHAR(40) NOT NULL REFERENCES Dealers(dealer_id),
    customer_id         NVARCHAR(40),
    customer_name       NVARCHAR(200),
    site                NVARCHAR(200),
    region              NVARCHAR(40) NOT NULL,
    install_date        DATE,
    -- NULL for a small number of assets. Policy 2.3: coverage cannot be
    -- determined and install_date must not be substituted.
    commissioning_date  DATE
);

CREATE TABLE AssetTelemetry (
    serial         NVARCHAR(40) NOT NULL REFERENCES Assets(serial),
    as_of_date     DATE NOT NULL,
    running_hours  INT NOT NULL,
    PRIMARY KEY (serial, as_of_date)
);

CREATE TABLE Claims (
    claim_id              NVARCHAR(40) PRIMARY KEY,
    serial                NVARCHAR(40) NOT NULL,
    dealer_id             NVARCHAR(40) NOT NULL REFERENCES Dealers(dealer_id),
    submitted_date        DATE NOT NULL,
    repair_date           DATE NOT NULL,
    operation_code        NVARCHAR(40) NOT NULL,
    claimed_part          NVARCHAR(40),
    claimed_labour_hours  DECIMAL(6,2) NOT NULL,
    goodwill_requested    DECIMAL(14,2),
    status                NVARCHAR(40) NOT NULL
);

CREATE TABLE ServiceHistory (
    job_id          NVARCHAR(40) PRIMARY KEY,
    serial          NVARCHAR(40) NOT NULL REFERENCES Assets(serial),
    job_date        DATE NOT NULL,
    operation_code  NVARCHAR(40) NOT NULL,
    component       NVARCHAR(40),
    part_fitted     NVARCHAR(40),
    labour_hours    DECIMAL(6,2),
    claim_id        NVARCHAR(40),
    completed_date  DATE
);

CREATE TABLE GoodwillAuthority (
    tier            INT PRIMARY KEY,
    max_amount_inr  DECIMAL(14,2),
    approver_role   NVARCHAR(200) NOT NULL
);

-- Reporting table. Maintained by hand and known to lag the bulletin documents.
-- Policy 1.4: where this table and a bulletin disagree, the bulletin governs.
CREATE TABLE TsbApplicability (
    tsb_id          NVARCHAR(40) PRIMARY KEY,
    family          NVARCHAR(40) NOT NULL,
    serial_from     INT,
    serial_to       INT,
    effective_from  DATE,
    status          NVARCHAR(40)
);

-- Action tables. Everything the agent writes is a draft; nothing pays or sends.
CREATE TABLE ClaimAdjudicationDraft (
    draft_id          NVARCHAR(40) PRIMARY KEY,
    claim_id          NVARCHAR(40) NOT NULL,
    decision          NVARCHAR(40) NOT NULL,
    payable           DECIMAL(14,2),
    currency          NVARCHAR(40),
    instrument_refs   NVARCHAR(MAX),
    notes             NVARCHAR(MAX),
    created_at        DATETIMEOFFSET(0) NOT NULL,
    created_by        NVARCHAR(MAX)
);

CREATE TABLE EvidenceRequest (
    request_id   NVARCHAR(40) PRIMARY KEY,
    claim_id     NVARCHAR(40) NOT NULL,
    field_name   NVARCHAR(40) NOT NULL,
    reason       NVARCHAR(MAX),
    created_at   DATETIMEOFFSET(0) NOT NULL
);

CREATE TABLE GoodwillEscalation (
    escalation_id  NVARCHAR(40) PRIMARY KEY,
    claim_id       NVARCHAR(40) NOT NULL,
    amount         DECIMAL(14,2) NOT NULL,
    approver_role  NVARCHAR(200) NOT NULL,
    created_at     DATETIMEOFFSET(0) NOT NULL,
    status         NVARCHAR(40) NOT NULL
);

CREATE INDEX idx_telemetry_serial ON AssetTelemetry(serial, as_of_date);
CREATE INDEX idx_history_serial   ON ServiceHistory(serial, job_date);
CREATE INDEX idx_claims_serial    ON Claims(serial);

